const test = require('node:test');
const assert = require('node:assert/strict');
const app = require('../lib/ascii-domain.cjs');
test('ASCII conversion and invalid domains', () => {
  for (const [domain,expected] of [
    ['mañana.com','xn--maana-pta.com'], ['例子.com','xn--fsqu00a.com'],
    ['EXAMPLE.COM','example.com'], ['xn--maana-pta.com','xn--maana-pta.com'],
    ['bad domain.com',''], ['xn--iñvalid.com',''], ['', '']
  ]) assert.equal(app.asciiDomain(domain),expected,domain);
});

